const CONTENT = {"id":"legacy:garrison-v2","version":4,"hash":"05bd02f82f15c1c7195f7c2896b6e8050fd68aeb9a2c240721079d8d511fa3ee","databaseCommit":"0ef7f952dfd018392200157a5c79a6511ba69122","historicalCommit":"86da4cfa3a4b958c3615fccf5afbc10b5c7f1bfb"};

